package com.codearena.controller;
import com.codearena.entity.*;import com.codearena.repository.*;
import org.springframework.beans.factory.annotation.Autowired;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
import org.springframework.data.domain.PageRequest;
import java.util.*;
@RestController public class SubmissionController {
 @Autowired SubmissionRepository submissions;@Autowired ProblemRepository problems;
 @PostMapping("/api/submissions") public ResponseEntity<?> create(@RequestBody Map<String,Object>b){String userId=(String)b.get("userId"),problemId=(String)b.get("problemId");if(userId==null||problemId==null)return ResponseEntity.badRequest().body(Map.of("error","userId and problemId required"));if(problems.findById(problemId).isEmpty()){Problem p=new Problem();p.setId(problemId);p.setTitle(b.get("problemTitle")!=null?(String)b.get("problemTitle"):"Problem "+problemId);p.setDescription("");p.setDifficulty(b.get("difficulty")!=null?(String)b.get("difficulty"):"Medium");p.setCategory("General");problems.save(p);}Submission s=new Submission();s.setUserId(userId);s.setProblemId(problemId);s.setCode((String)b.get("code"));s.setLanguage((String)b.get("language"));s.setStatus((String)b.get("status"));s.setVerdict((String)b.get("verdict"));if(b.get("runtime")!=null)s.setRuntime((int)Math.round(((Number)b.get("runtime")).doubleValue()));if(b.get("memory")!=null)s.setMemory((int)Math.round(((Number)b.get("memory")).doubleValue()));s.setPassed(b.get("passed")!=null?((Number)b.get("passed")).intValue():0);s.setTotal(b.get("total")!=null?((Number)b.get("total")).intValue():0);try{s=submissions.save(s);return ResponseEntity.ok(Map.of("success",true,"submission",s));}catch(Exception e){return ResponseEntity.status(500).body(Map.of("error","Failed to save submission"));}}
 @GetMapping("/api/submissions") public ResponseEntity<?> list(@RequestParam String userId){if(userId==null)return ResponseEntity.badRequest().body(Map.of("error","userId required"));List<Submission>s=submissions.findByUserIdOrderByCreatedAtDesc(userId,PageRequest.of(0,50));List<Map<String,Object>>out=new ArrayList<>();for(Submission x:s){Map<String,Object>m=new LinkedHashMap<>();m.put("id",x.getId());m.put("userId",x.getUserId());m.put("problemId",x.getProblemId());m.put("code",x.getCode());m.put("language",x.getLanguage());m.put("status",x.getStatus());m.put("verdict",x.getVerdict());m.put("runtime",x.getRuntime());m.put("memory",x.getMemory());m.put("passed",x.getPassed());m.put("total",x.getTotal());m.put("createdAt",x.getCreatedAt());Optional<Problem> problem=problems.findById(x.getProblemId());if(problem.isPresent())m.put("problem",Map.of("title",problem.get().getTitle(),"difficulty",problem.get().getDifficulty()));out.add(m);}return ResponseEntity.ok(Map.of("submissions",out));}
}
